using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // Breaking change 1: EF Core 9 renamed the default discriminator
            // property from "Discriminator" to "$type". Existing 500K documents
            // use "Discriminator", and direct SQL queries reference c.Discriminator,
            // so we must preserve the old property name.
            entity.HasDiscriminator<string>("Discriminator");

            // Breaking change 2: EF Core 9 no longer prepends the discriminator
            // to the id value. Existing documents have ids like "Product|123".
            // Opt back into the legacy format so reads match existing documents.
            entity.HasPartitionKey(p => p.Id);
            entity.Property(p => p.Id)
                  .HasValueGeneratorFactory<Microsoft.EntityFrameworkCore.Cosmos.ValueGeneration.IdValueGeneratorFactory>();
        });

        // Breaking change 3: HasIndex is not supported by the Cosmos provider
        // in EF Core 9 (throws at model validation). Cosmos manages indexes
        // server-side via indexing policy; remove the client-side declaration.
    }

    protected override void ConfigureConventions(ModelConfigurationBuilder configurationBuilder)
    {
        // Preserve the EF Core 8 id format "EntityType|KeyValue" for all entities
        // so existing documents remain readable.
        configurationBuilder.Conventions.Add(_ =>
            new Microsoft.EntityFrameworkCore.Cosmos.Infrastructure.IdValueGeneratorConvention());
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } }

